// Local Editor baseline, isolated from captures and Frame Debugger; not a runtime component.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Profiling;
using Unity.Profiling;using Unity.Profiling.LowLevel.Unsafe;using Newtonsoft.Json;
public static class EnergyClusterPerformance {
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/EnergyCluster/V6");
 class Phase{public int count,repeat;public bool spread;}
 class Row{public int phase,frame,batches,draws,setPass,particles;public double main,render,gpu,update,gc;}
 static List<Phase> phases=new List<Phase>();static List<Row> rows=new List<Row>(12000);static List<GameObject> clones=new List<GameObject>(),hidden=new List<GameObject>();static List<bool> active=new List<bool>();static List<object> memory=new List<object>();static Dictionary<string,ProfilerRecorder> counters=new Dictionary<string,ProfilerRecorder>();static ParticleSystem[] systems;static int phase=-1,frame=-1;static double begin;static bool background;static EditorWindow focused;static object environment;
 static double Read(string n,bool ms=true){ProfilerRecorder r;return counters.TryGetValue(n,out r)&&r.Valid&&r.Count>0?r.LastValue/(ms?1000000.0:1):double.NaN;}
 static object Stats(IEnumerable<double> data){var a=data.Where(x=>!double.IsNaN(x)&&!double.IsInfinity(x)).OrderBy(x=>x).ToArray();return a.Length==0?(object)new{available=false}:new{count=a.Length,median=a[a.Length/2],p95=a[(int)((a.Length-1)*.95)],max=a[a.Length-1]};}
 static void Next(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();phase++;if(phase>=phases.Count){Finish();return;}var ph=phases[phase];for(int i=0;i<ph.count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/EnergyCluster/Prefabs/VFX_EnergyCluster_Loop.prefab"));g.name="EnergyCluster_Perf_Temporary";g.transform.position=ph.spread?new Vector3((i%4-1.5f)*2,(i/4-.5f)*2,0):new Vector3(0,0,0);clones.Add(g);}systems=clones.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>()).ToArray();begin=Time.timeAsDouble;memory.Add(new{phase,allocated=Profiler.GetTotalAllocatedMemoryLong(),reserved=Profiler.GetTotalReservedMemoryLong()});File.WriteAllText(Path.Combine(Out,"PerformanceProgress.json"),JsonConvert.SerializeObject(new{phase,total=phases.Count,ph.count,ph.repeat,ph.spread}));}
 static void Finish(string error=null){EditorApplication.update-=Tick;foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);for(int i=0;i<hidden.Count;i++)if(hidden[i]!=null)hidden[i].SetActive(active[i]);Application.runInBackground=background;foreach(var r in counters.Values)r.Dispose();if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"PerformanceRaw.json"),JsonConvert.SerializeObject(new{environment,phases,rows,memory},Formatting.Indented));var groups=rows.GroupBy(r=>new{phases[r.phase].count,phases[r.phase].spread}).Select(g=>new{instances=g.Key.count,g.Key.spread,frames=g.Count(),batches=Stats(g.Select(r=>(double)r.batches)),draws=Stats(g.Select(r=>(double)r.draws)),setPass=Stats(g.Select(r=>(double)r.setPass)),mainMs=Stats(g.Select(r=>r.main)),renderMs=Stats(g.Select(r=>r.render)),gpuMs=Stats(g.Select(r=>r.gpu)),particleUpdateMs=Stats(g.Select(r=>r.update)),gcBytes=Stats(g.Select(r=>r.gc)),particles=Stats(g.Select(r=>(double)r.particles))}).ToArray();File.WriteAllText(Path.Combine(Out,"PerformanceSummary.json"),JsonConvert.SerializeObject(new{success=error==null,error,method="Actual Play Mode: 0/1/8/32 overlapped, two repetitions, plus 8 spatially distributed. 0.8s warmup + 2.2s sample each phase, every other engine frame. Whole-frame Editor counters, including UI/probe. Concurrent counts are exploratory, not game requirements. No screenshot or Frame Debugger during timing.",environment,counters=counters.Keys,groups,memory,restored=true,pending=new[]{"Target PC Player and business concurrency/budget","Per-pass GPU and overdraw","Long-run pool memory","Precise batch break/merge reasons if frame-event details unavailable"}},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Stopped externally");return;}if(frame==Time.frameCount||Time.frameCount%2!=0)return;frame=Time.frameCount;var elapsed=Time.timeAsDouble-begin;if(elapsed>=3){Next();return;}if(elapsed<.8)return;int particles=0;foreach(var p in systems)particles+=p.particleCount;rows.Add(new Row{phase=phase,frame=frame,batches=UnityStats.batches,draws=UnityStats.drawCalls,setPass=UnityStats.setPassCalls,particles=particles,main=Read("CPU Main Thread Frame Time"),render=Read("CPU Render Thread Frame Time"),gpu=Read("GPU Frame Time"),update=Read("ParticleSystem.Update"),gc=Read("GC Allocated In Frame",false)});}catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets")throw new Exception("Wrong scope/state");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();foreach(var g in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.GetComponent<Camera>()==null)){hidden.Add(g);active.Add(g.activeSelf);g.SetActive(false);}var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);foreach(var name in new[]{"CPU Main Thread Frame Time","CPU Render Thread Frame Time","GPU Frame Time","ParticleSystem.Update","GC Allocated In Frame"}){var h=handles.FirstOrDefault(x=>ProfilerRecorderHandle.GetDescription(x).Name==name);if(h.Valid){var d=ProfilerRecorderHandle.GetDescription(h);counters[name]=ProfilerRecorder.StartNew(d.Category,name,1);}}var cam=Camera.main;environment=new{unity=Application.unityVersion,pipeline=GraphicsSettings.currentRenderPipeline.name,colorSpace=QualitySettings.activeColorSpace.ToString(),device=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),editor=true,width=cam.pixelWidth,height=cam.pixelHeight,orthographicSize=cam.orthographicSize,hdr=cam.allowHDR,msaa=cam.allowMSAA,vsync=QualitySettings.vSyncCount};for(int repeat=0;repeat<2;repeat++)foreach(int n in new[]{0,1,8,32})phases.Add(new Phase{count=n,repeat=repeat});phases.Add(new Phase{count=8,repeat=0,spread=true});Next();EditorApplication.update+=Tick;return "Nine isolated native performance phases started (~27 engine seconds).";}
}
